upstream ab_test {
    zone ab 64k;
    server 10.0.0.10:8080;
    server 10.0.0.100:8080;
}
split_clients "${arg_variant}" $upstream {
    50%     ab_test;
    50%     ab_test;
}
server {
    listen 80;
    server_name test.example.com;
    location / {
        proxy_pass http://ab_test;
        add_header X-Ab-Variant $upstream;
    }
}

upstream blue {
    zone blue 64k;
    server 10.0.0.50:8080 max_fails=3 fail_timeout=30s;
}
upstream green {
    zone green 64k;
    server 10.0.0.51:8080 max_fails=3 fail_timeout=30s;
}

upstream weighted {
    zone weighted 64k;
    server 10.0.0.10:8080 weight=50;
    server 10.0.0.11:8080 weight=30;
    server 10.0.0.12:8080 weight=15;
    server 10.0.0.13:8080 weight=5;
}

upstream stable { server 10.0.0.10:8080; }
upstream canary { server 10.0.0.100:8080; }
server {
    listen 80;
    server_name deploy.example.com;
    set $backend "stable";
    if ($cookie_canary = "1") { set $backend "canary"; }
    location / { proxy_pass http://$backend; }
}
